/** 842 -> "842", 1280 -> "1.3k", 12400 -> "12k": a number that always fits a chip. */
export function compactCount(n: number, locale = 'en'): string {
  const v = Math.max(0, Math.floor(n));
  if (v < 1000) return String(v);
  return new Intl.NumberFormat(locale, { notation: 'compact', maximumFractionDigits: v < 10_000 ? 1 : 0 }).format(v).toLowerCase();
}

/** "bg_ember:0000" -> "bg_ember": the item a spend line was for. */
export const spendItemOf = (refId: string | null): string | null => (refId ? refId.split(':')[0] : null);

/** A name generated by provisioning, "Tera <Word> <3 digits>" (e.g. "Tera Curioso 482"). */
export const isGeneratedTeraName = (name: string): boolean => /^Tera\s+[\p{L}]+\s+\d{3}$/u.test(name.trim());

type Translate = (key: string, params?: Record<string, string | number>) => string;

/** A ledger line in words: an earn reason, a spend (with the item's name when known), or a neutral fallback. */
export function ledgerLabel(reason: string, refId: string | null, t: Translate, itemTitle: (key: string) => string | null): string {
  if (reason === 'spend') {
    const key = spendItemOf(refId);
    if (key === 'life') return t('crystals.reason.spendLife');
    const title = key ? itemTitle(key) : null;
    return title ? `${t('crystals.reason.spend')} · ${title}` : t('crystals.reason.spend');
  }
  if (reason === 'refund') return t('crystals.reason.refund');
  const known = `crystals.reason.${reason}`;
  const text = t(known);
  return text === known ? t('crystals.reason.unknown') : text;
}
